from pathlib import Path
import json,hashlib,re
p=Path(__file__).resolve().parent
read=lambda n:json.loads((p/n).read_text())
pct=lambda a,b:round((b/a-1)*100,3)
runtime=read('runtime-manifest.json');snapshot=read('bench-runtime-sha256.json')
for row in runtime:assert hashlib.sha256((p/'runtime'/row['path']).read_bytes()).hexdigest()==row['sha256']==snapshot['candidate'][row['path']]
tests=(p/'tests.log').read_text();assert re.search(r'^# pass 1734$',tests,re.M) and re.search(r'^# fail 0$',tests,re.M)
first=[]
for file in ['native-first-load-results.json','native-filled-first-load-results.json']:
 d=read(file);rows=[]
 for row in d['comparisons']:
  a,b=row['baseline'],row['candidate'];rows.append({'scenario':row['scenario'],'baselineMs':a['medianMs'],'candidateMs':b['medianMs'],'elapsedPercent':pct(a['medianMs'],b['medianMs']),'peakHeapPercent':pct(a['sampledMaxHeapBytes'],b['sampledMaxHeapBytes'])})
 first.append({'report':file,'processes':len(d['runs']),'rows':rows})
paired=read('paired-loon-results.json');pairs=[]
for row in paired['comparisons']:
 a,b=row['baseline'],row['candidate'];pairs.append({'kind':row['kind'],'format':row['format'],'baseline':a,'candidate':b,'elapsedPercent':pct(a['elapsedMs'],b['elapsedMs']),'peakHeapPercent':pct(a['sampledMaxHeapBytes'],b['sampledMaxHeapBytes']),'retainedHeapPercent':pct(a['retainedHeapBytes'],b['retainedHeapBytes'])})
jsc=read('mixed-jsc-results.json');jrows=[]
for row in jsc['comparisons']:
 a,b=row['baseline'],row['candidate'];jrows.append({'mode':row['mode'],'scenario':row['scenario'],'baselineMs':a['milliseconds'],'candidateMs':b['milliseconds'],'elapsedPercent':pct(a['milliseconds'],b['milliseconds']),'peakFootprintPercent':pct(a['sampledPeakFootprint'],b['sampledPeakFootprint'])})
mixed=read('mixed-native-churn-results.json');pressure=read('native-pressure-results.json');live=read('user-track-live-results.json');work=read('work-results.json');features=read('feature-results.json')
summary={'version':'3.1.5','adapter':15,'baselineVersion':'3.1.4','baselineRuntime':'1e76330ca4427bd966f17471196a1b1f41f1cac5','tests':{'passed':1734,'failed':0,'addedSince314':51,'egernYAML':'passed'},'runtime':runtime,'work':work,'firstLoad':first,'pairedLoon':{'processes':len(paired['runs']),'rows':pairs},'jsc':{'processes':len(jsc['runs']),'rows':jrows},'mixedChurn':{'configurations':len(mixed['results']),'responses':sum(r['lyricResponses'] for r in mixed['results']),'warmHTTP':sum(r['warmHTTP'] for r in mixed['results']),'peakHTTP':max(r['maxActiveHTTP'] for r in mixed['results'])},'pressure':{'processes':len(pressure['runs']),'peakLiveInvocations':max(r['peakLiveInvocations'] for r in pressure['runs']),'peakHTTP':max(r['peakHTTP'] for r in pressure['runs']),'admissionTimers':max(r['admissionTimers'] for r in pressure['runs'])},'userTrack':{'baseline':live['baseline'],'candidate':live['candidate'],'actualRequests':len(live['trace']),'nativeReplays':len(live['nativeReplays']),'scope':live['scope']},'featureInvocations':features['invocations'],'limitsChanged':False,'scope':'Real service source checks, compiled native host mocks, desktop Node and macOS JSC sampling. Not actual iPhone Spotify UI, every allocation, native buffers or VPN acceptance. All regressions are retained; synthetic service latency is zero.'}
(p/'validation-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
lines=['# VerseLyrics 3.1.5 measurements','',summary['scope'],'','The final runtime hashes are checked before and after every measurement step. The same fixture codec and host harness are used for both versions; only the compiled native runtime differs. Source/decoder work instrumentation is separate from uninstrumented heap/timing runs.','', '## Actual work reduction','', '| Operation | 3.1.4 | 3.1.5 |','| --- | ---: | ---: |']
a,b=work['results'];
for label,old,new in [('600-row generic varint result objects',a['parse']['genericVarintResults'],b['parse']['genericVarintResults']),('600-row UTF-16 scratch allocations',a['parse']['typedScratchAllocations'],b['parse']['typedScratchAllocations']),('Cumulative scratch bytes in that parse',a['parse']['totalTypedScratchBytes'],b['parse']['totalTypedScratchBytes']),('Mixed cold query strings constructed',a['mixedCold']['queryStringsConstructed'],b['mixedCold']['queryStringsConstructed']),('Mixed cold Latin scanner objects',a['mixedCold']['latinScannerObjects'],b['mixedCold']['latinScannerObjects']),('Mixed warm query strings constructed',a['mixedWarm']['queryStringsConstructed'],b['mixedWarm']['queryStringsConstructed'])]:lines.append(f'| {label} | {old} | {new} |')
lines+=['','Both mixed cases still use one cold HTTP request with one deduplicated q and zero warm HTTP. The 43,200-to-72 byte row is cumulative scratch allocation in one deterministic 600-row parse, not whole-process peak memory. The reusable scratch is capped at 8,194 bytes and strings do not alias it.','', '## First load: fresh Node processes','', 'Each table has twelve alternating trials per version and scenario (312 processes). One fresh native script/VM per child, 32 MiB old-space. Samples at invocation, HTTP and completion boundaries include common harness/code-cache overhead; they are not all transient peaks or actual network waiting time. The filled-cache table starts with 48,000-60,000 unrelated serialized characters.','']
for group in first:
 lines+=['### '+group['report'],'','| Scenario | Baseline ms | Candidate ms | Time change | Sampled heap change |','| --- | ---: | ---: | ---: | ---: |']
 for row in group['rows']:lines.append(f"| {row['scenario']} | {row['baselineMs']:.3f} | {row['candidateMs']:.3f} | {row['elapsedPercent']:+.3f}% | {row['peakHeapPercent']:+.3f}% |")
 lines.append('')
lines+=['## Loon repeated playlist comparison','','Five alternating fresh process pairs for each of the four cases (40 processes). Plain cases contain 240 cold songs and 720 HTTP calls; mixed cases contain 120 song IDs, 240 lyric responses and 120 HTTP calls, including a zero-HTTP warm reopen for every song. Both versions use the same codec and cache priming. GC runs every six songs. Output hashes and request counts agree.','', '| Case | Format | Baseline ms | Candidate ms | Time change | Sampled heap change | Retained heap change |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
for row in pairs:lines.append(f"| {row['kind']} | {row['format']} | {row['baseline']['elapsedMs']:.3f} | {row['candidate']['elapsedMs']:.3f} | {row['elapsedPercent']:+.3f}% | {row['peakHeapPercent']:+.3f}% | {row['retainedHeapPercent']:+.3f}% |")
lines+=['','The separate native-churn report retains a single functional run for baseline Loon and all five candidate clients. Use the five-pair medians above for the repeated Loon comparison; no individual outlier is discarded.','', '## macOS JavaScriptCore','', 'Six alternating fresh-process trials per case/version (360 processes). Cold uses one context; sequence uses 32 fresh contexts without forced GC. Reported physical footprints include harness/JIT/allocator costs. All native output byte hashes and HTTP counts match between versions.','', '| Mode | Scenario | Time change | Peak footprint change |','| --- | --- | ---: | ---: |']
for row in jrows:lines.append(f"| {row['mode']} | {row['scenario']} | {row['elapsedPercent']:+.3f}% | {row['peakFootprintPercent']:+.3f}% |")
lines+=['','There are regressions as well as improvements in these tables, including a roughly 3.1% sampled Node heap increase in the cold repeated-chorus case and some JSC time/footprint increases. Runtime bytes also grow: Loon lyrics 89,305 to 90,439 bytes, entry 30,410 to 30,605. Smaller allocation counts do not prove every process peak or device wait decreases.','', '## Preserved behavior, rapid arrivals and real source check','', '- 1,734 automated tests pass, including 51 new cases. Egern native YAML checks pass.','- Twenty client/format/cache-mode mixed playlists produce 4,800 native responses; warm reopen HTTP remains zero and at most one service request is active.','- Sixteen rapid-arrival processes retain at most two live invocations, one active HTTP request and zero admission timers in the fixture. Retired callbacks settle before completion. These counts are mocks, not an atomic native storage guarantee.','- Sixty compiled native feature invocations preserve static replacement on/off, missing fallback, filler filtering, useful mixed-English translation, colors and the existing cache limits.','- For the supplied track, real public Spotify metadata and QQ catalog/lyric responses reproduce the old mismatch. Baseline 3.1.4 keeps the self-written static fixture; 3.1.5 obtains 65 real timed rows in two QQ requests. Ten native replays preserve those replies and reuse warm lyrics without requests. The static input is a fixture, not captured Spotify phone traffic. Translation is disabled only in this focused source probe. Downloaded lyric text is excluded from the release; counts/hashes are in user-track-live-results.json.','', '## Rejected experiment','', 'A strict JavaScript scanner for opaque cache values was tried and removed. Some filled-cache samples allocated less, but playlist processing became substantially slower and entry scripts exceeded the existing size budget. The final runtime hashes match the pre-experiment verified parser; the slower scanner is not shipped.','', '## Reproduction','', 'Run the commands in README.md with an unchanged 3.1.4 stage. run-measurements-315.py records all final runtime SHA256 values and runs each measurement serially. The full JSON reports preserve individual trials. First-load and paired playlist timing are desktop script processing with zero service latency. iPhone Spotify UI, native response buffers and VPN stability have not been measured.']
(p/'MEASUREMENTS.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'tests':1734,'firstLoadProcesses':sum(g['processes'] for g in first),'pairedProcesses':len(paired['runs']),'jscProcesses':len(jsc['runs']),'mixedResponses':summary['mixedChurn']['responses'],'sourceRows':live['candidate']['rows'],'paired':[{k:r[k] for k in ['kind','format','elapsedPercent','peakHeapPercent']} for r in pairs]}))
